package httpserver

import (
	"io"
	"net/http"
)

func renderBonusDistributionWorkspace(w http.ResponseWriter) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = io.WriteString(w, bonusDistributionWorkspacePage)
}

func bonusDistributionWorkspaceScript(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
	_, _ = io.WriteString(w, bonusDistributionWorkspaceJavaScript)
}

const bonusDistributionWorkspacePage = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>奖金分配</title><style>` + bonusDistributionWorkspaceCSS + `[hidden]{display:none!important}</style></head><body>
<header class="top"><a class="brand" href="./"><span>BD</span><strong>奖金分配</strong></a><div class="credential"><span id="credentialState">尚未连接</span><button id="openCredential" class="quiet">设置访问凭证</button></div></header>
<div class="layout"><aside class="rail"><p class="eyebrow">C7 人工作台</p><button class="nav active" data-view="overview">使用说明</button><button class="nav" data-view="workspace">奖池工作区</button><div class="rail-note"><strong>事实边界</strong><span>本应用拥有奖金计算、分配与状态；Project、结算、回款、Person 和 Assignment 只以精确 revision 快照接入。</span></div></aside><main>
<section id="overview" class="view active"><div class="intro"><p class="eyebrow">Bonus Distribution</p><h1>从已确认来源计算奖金，再以可追溯的方式发布、替代或撤回。</h1><p>经营奖金读取 Contract Settlement，生产奖金读取 Money Receipt Set。策略、来源、参与人和分配结果都会被冻结；任何纠错都保留旧 revision。</p><button class="primary" data-go="workspace">进入奖池工作区</button></div><div class="flow"><article><b>01</b><h2>选择真实来源</h2><p>输入 Project、来源、Person 与 Assignment 的精确 ID 和 revision。</p></article><article><b>02</b><h2>核对草稿</h2><p>查看来源摘要、策略公式、金额和服务端允许动作。</p></article><article><b>03</b><h2>发布或纠错</h2><p>发布草稿；纠错时用新草稿原子替代旧奖池，历史不被覆盖。</p></article></div></section>
<section id="workspace" class="view"><div class="section-head"><div><p class="eyebrow">Project 范围</p><h1>奖金池与分配</h1></div><div class="actions"><button id="newBusiness" class="primary" disabled>建立经营草稿</button><button id="newProduction" class="quiet" disabled>建立生产草稿</button></div></div>
<form id="projectForm" class="project-bar"><label>Project ID<input id="projectID" required placeholder="稳定 UUID"></label><button class="quiet" type="submit">读取当前事实</button></form>
<div class="mode-tabs" role="tablist"><button type="button" class="mode active" data-mode="all">全部</button><button type="button" class="mode" data-mode="business">经营奖金</button><button type="button" class="mode" data-mode="production">生产奖金</button></div>
<div id="notice" class="notice">设置访问凭证并输入 Project ID。页面不会把权限拒绝、依赖失败或金额脱敏伪装成空数据。</div>
<div class="workspace-grid"><section class="panel"><div class="panel-head"><div><h2>奖池列表</h2><span id="projectContext">尚未选择 Project</span></div><button id="reload" class="quiet" disabled>重新读取</button></div><div id="poolList" class="record-list"><div class="empty"><strong>还没有读取奖池事实</strong><span>从上方输入 Project ID 开始。</span></div></div></section>
<aside class="panel detail"><div class="panel-head"><div><h2>详情、历史与恢复</h2><span>动作完全来自服务端 allowed_actions。</span></div></div><div id="detail"><div class="empty">选择一条奖池。</div></div><div id="historyList" class="timeline"></div></aside></div></section></main></div>
<dialog id="credentialDialog"><form method="dialog" id="credentialForm"><p class="eyebrow">访问控制</p><h2>连接受保护 API</h2><p>本地验证粘贴模板 Token；正式组合由 Gateway 从 IAM 会话换取短期凭证。Token 只保存在当前标签页。</p><label>Bearer Token<textarea id="token" rows="5" required></textarea></label><div class="dialog-actions"><button value="cancel" class="quiet">取消</button><button value="default" class="primary">保存并连接</button></div></form></dialog>
<dialog id="draftDialog"><form method="dialog" id="draftForm"><p class="eyebrow" id="draftEyebrow">建立奖金草稿</p><h2 id="draftTitle">建立经营奖金草稿</h2><input name="bonus_type" type="hidden"><div class="form-grid"><label>Project revision<input name="project_revision" type="number" min="1" required></label><label id="sourceLabel">Settlement ID<input name="source_id" required></label><label>来源 revision<input name="source_revision" type="number" min="1" required></label><label>策略 Key<input name="policy_key" value="reference-oa-bonus-v1" required></label><label>策略版本<input name="policy_version" value="1.0.0" required></label><label>奖金比例（basis points）<input name="rate_basis_points" type="number" min="1" max="10000" value="1000" required></label><label>取整规则<select name="rounding"><option value="half_up">half_up</option></select></label></div><div class="allocation-head"><div><h3>参与人分配</h3><p>比例合计必须为 10000；Person 与 Assignment 必须属于该 Project 且类型适用。</p></div><button id="addAllocation" type="button" class="quiet">增加参与人</button></div><div id="allocationRows" class="allocation-rows"></div><div class="dialog-actions"><button value="cancel" class="quiet">取消</button><button value="default" class="primary">计算并保存草稿</button></div></form></dialog>
<dialog id="supersedeDialog"><form method="dialog" id="supersedeForm"><p class="eyebrow">追加式纠错</p><h2>用新草稿替代已发布奖池</h2><p>旧奖池会变为 superseded，新草稿会原子发布；两者历史和关联都保留。</p><label>替代草稿<select name="replacement_pool_id" required></select></label><label>纠错原因<textarea name="reason" rows="3" required></textarea></label><div class="dialog-actions"><button value="cancel" class="quiet">取消</button><button value="default" class="primary">确认原子替代</button></div></form></dialog>
<script src="assets/bonus-distribution.js"></script></body></html>`

const bonusDistributionWorkspaceCSS = `:root{font-family:Inter,"PingFang SC","Microsoft YaHei",ui-sans-serif,system-ui,sans-serif;color:#192230;background:#f3f5f7;line-height:1.55;--ink:#192230;--muted:#667085;--line:#d9dfe7;--soft:#f7f8fa;--accent:#334f86;--danger:#9b3535}*{box-sizing:border-box}body{margin:0}.top{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 28px;background:#fff;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:11px;color:var(--ink);text-decoration:none}.brand span{display:grid;place-items:center;width:34px;height:34px;border-radius:7px;background:#25385a;color:#fff;font-size:12px;font-weight:800}.credential{display:flex;align-items:center;gap:10px;color:var(--muted);font-size:13px}.layout{display:grid;grid-template-columns:220px minmax(0,1fr);min-height:calc(100vh - 64px)}.rail{padding:26px 18px;background:#fff;border-right:1px solid var(--line)}.eyebrow{margin:0 0 9px;color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.nav{width:100%;padding:11px 13px;border:0;border-left:3px solid transparent;background:transparent;color:#4d596b;text-align:left;font:inherit;cursor:pointer}.nav.active{border-color:var(--accent);background:#edf2f8;color:var(--accent);font-weight:750}.rail-note{display:grid;gap:5px;margin-top:32px;padding:14px;border-top:1px solid var(--line);color:var(--muted);font-size:12px}main{min-width:0;padding:30px}.view{display:none}.view.active{display:block}.intro{min-height:330px;padding:52px;border:1px solid var(--line);border-radius:12px;background:linear-gradient(120deg,#fff 68%,#e9eef6)}h1,h2,h3,p{margin-top:0}.intro h1{max-width:830px;margin-bottom:18px;font-size:clamp(34px,5vw,56px);line-height:1.08;letter-spacing:-.04em}.intro>p:not(.eyebrow){max-width:760px;color:var(--muted);font-size:17px}.flow{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}.flow article,.panel{border:1px solid var(--line);border-radius:10px;background:#fff}.flow article{padding:22px}.flow b{color:var(--accent)}.flow h2{margin:12px 0 6px;font-size:17px}.flow p{margin:0;color:var(--muted);font-size:13px}.primary,.quiet,.danger,.mode{padding:9px 13px;border:1px solid transparent;border-radius:6px;font:inherit;font-size:13px;font-weight:700;cursor:pointer}.primary{background:var(--accent);color:#fff}.quiet,.mode{border-color:var(--line);background:#fff;color:#3f4a5a}.danger{background:var(--danger);color:#fff}.primary:disabled,.quiet:disabled{opacity:.45;cursor:not-allowed}.section-head,.panel-head,.card-head,.dialog-actions,.mode-tabs,.allocation-head,.actions{display:flex;align-items:center;justify-content:space-between;gap:12px}.section-head{margin-bottom:16px}.section-head h1{margin:0;font-size:28px}.actions{justify-content:flex-start;flex-wrap:wrap}.project-bar{display:grid;grid-template-columns:minmax(280px,620px) auto;gap:10px;align-items:end;padding:14px;border:1px solid var(--line);border-radius:9px;background:#fff}.mode-tabs{justify-content:flex-start;margin:14px 0}.mode.active{border-color:var(--accent);background:#edf2f8;color:var(--accent)}.notice{margin:12px 0;padding:11px 14px;border:1px solid #cad8ea;border-radius:7px;background:#eef4fb;color:#315477;font-size:13px}.notice.ok{border-color:#bce0cb;background:#eefaf3;color:#15623d}.notice.error{border-color:#efc6c6;background:#fff2f2;color:#922}.workspace-grid{display:grid;grid-template-columns:minmax(0,1.22fr) minmax(390px,1fr);gap:16px}.panel{min-height:570px;padding:18px}.panel-head{padding-bottom:14px;border-bottom:1px solid var(--line)}.panel-head h2{margin:0;font-size:18px}.panel-head span{color:var(--muted);font-size:12px}.record-list{display:grid;gap:10px;margin-top:14px}.record-card{padding:15px;border:1px solid var(--line);border-left:4px solid var(--accent);border-radius:8px;cursor:pointer}.record-card.selected{box-shadow:0 0 0 2px #334f8633}.record-card.withdrawn,.record-card.superseded{border-left-color:var(--danger);background:#fffafa}.card-head h3{margin:0;font-size:16px}.badges{display:flex;flex-wrap:wrap;gap:6px}.badge{padding:3px 8px;border-radius:999px;background:#eef1f4;color:#566273;font-size:11px;font-weight:750}.facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:12px 0}.fact{padding:10px;background:var(--soft);border-radius:6px}.fact small{display:block;color:var(--muted)}.fact strong{font-size:13px}.source{margin:0;color:var(--muted);font-size:12px;overflow-wrap:anywhere}.detail-block{padding:14px 0;border-bottom:1px solid var(--line)}.detail-block h3{margin-bottom:8px;font-size:15px}.empty{display:grid;gap:5px;place-content:center;min-height:180px;color:var(--muted);text-align:center}.timeline{display:grid;gap:9px;margin-top:14px}.event{padding:12px;border-left:3px solid #bdc6d2;background:var(--soft);font-size:12px}.event strong{display:block;color:var(--ink)}label{display:grid;gap:5px;color:#4c5667;font-size:12px;font-weight:700}input,textarea,select{width:100%;padding:9px 10px;border:1px solid #cbd2dc;border-radius:5px;background:#fff;color:var(--ink);font:inherit;font-size:13px}.form-grid,.allocation-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.allocation-head{margin:18px 0 10px}.allocation-head h3{margin-bottom:2px}.allocation-head p{margin:0;color:var(--muted);font-size:12px}.allocation-rows{display:grid;gap:10px}.allocation-row{padding:12px;border:1px solid var(--line);border-radius:7px;background:var(--soft)}.allocation-row .wide{grid-column:1/-1}.allocation-row button{justify-self:end}.wide{grid-column:1/-1}dialog{width:min(780px,calc(100vw - 32px));padding:24px;border:1px solid var(--line);border-radius:11px;box-shadow:0 18px 50px #18212f2a}dialog::backdrop{background:#18212f66}.dialog-actions{margin-top:18px;justify-content:flex-end}@media(max-width:980px){.layout{grid-template-columns:1fr}.rail{display:none}main{padding:18px}.flow,.workspace-grid{grid-template-columns:1fr}.project-bar,.form-grid,.allocation-row{grid-template-columns:1fr}.wide,.allocation-row .wide{grid-column:auto}.section-head{align-items:flex-start;flex-direction:column}}`

const bonusDistributionWorkspaceJavaScript = `const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],gatewayMode=location.pathname!=='/'&&!location.pathname.startsWith('/assets/'),state={token:sessionStorage.getItem('bonus-distribution-demo-token')||'',projectID:'',mode:'all',items:[],collectionActions:[],selected:null};
const A={businessCalculate:'bonus-pool.business.calculate',businessPublish:'bonus-pool.business.publish',businessSupersede:'bonus-pool.business.supersede',businessWithdraw:'bonus-pool.business.withdraw',productionCalculate:'bonus-pool.production.calculate',productionPublish:'bonus-pool.production.publish',productionSupersede:'bonus-pool.production.supersede',productionWithdraw:'bonus-pool.production.withdraw',poolHistory:'bonus-pool.history.read',allocationHistory:'bonus-allocation.read'};
function notice(message,kind=''){const n=$('#notice');n.textContent=message;n.className='notice '+kind}function esc(v){const s=document.createElement('span');s.textContent=v??'';return s.innerHTML}function money(v,c='CNY'){return v==null?'金额未授权':new Intl.NumberFormat('zh-CN',{style:'currency',currency:c||'CNY'}).format(v/100)}function can(item,action){return (item?.allowed_actions||[]).includes(action)}function typeName(v){return v==='business'?'经营奖金':'生产奖金'}
async function api(path,options={}){const headers={Accept:'application/json',...(state.token?{Authorization:'Bearer '+state.token}:{}),...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})};const response=await fetch(path.replace(/^\//,''),{...options,headers});const body=await response.json().catch(()=>({}));if(!response.ok){const error=new Error(body.error?.code||'HTTP_'+response.status);error.status=response.status;error.retryable=body.error?.retryable;throw error}return body}
function filtered(){return state.mode==='all'?state.items:state.items.filter(x=>x.bonus_type===state.mode)}function setButtons(){const ready=!!state.projectID;$('#newBusiness').disabled=!ready||!state.collectionActions.includes(A.businessCalculate);$('#newProduction').disabled=!ready||!state.collectionActions.includes(A.productionCalculate)}
function render(){const root=$('#poolList'),items=filtered();root.replaceChildren();setButtons();if(!items.length){root.innerHTML='<div class="empty"><strong>当前筛选下没有奖金池</strong><span>有 calculate 权限时可建立第一条草稿；无权不是空数据。</span></div>';renderDetail();return}for(const item of items){const card=document.createElement('article');card.className='record-card '+item.state+(state.selected?.id===item.id?' selected':'');card.innerHTML='<div class="card-head"><div><h3>'+typeName(item.bonus_type)+'</h3><div class="badges"><span class="badge">'+esc(item.state)+'</span><span class="badge">revision '+item.revision+'</span></div></div><strong>'+money(item.amount_minor,item.currency)+'</strong></div><div class="facts"><div class="fact"><small>Project</small><strong>'+esc(item.project?.display_name||item.project?.id)+'</strong></div><div class="fact"><small>来源</small><strong>'+esc(item.source?.type)+' · r'+item.source?.revision+'</strong></div></div><p class="source">ID：'+esc(item.id)+'</p>';card.onclick=()=>{state.selected=item;render();renderDetail()};root.append(card)}}
function relation(item){const rows=[];if(item.supersedes)rows.push('替代 '+esc(item.supersedes.pool_id)+' · r'+item.supersedes.revision);if(item.superseded_by)rows.push('被 '+esc(item.superseded_by.pool_id)+' · r'+item.superseded_by.revision+' 替代');return rows.length?rows.join('<br>'):'没有替代关系'}
function renderDetail(){const root=$('#detail');$('#historyList').replaceChildren();const item=state.selected;if(!item){root.innerHTML='<div class="empty">选择一条奖池。</div>';return}const actions=[];const publish=item.bonus_type==='business'?A.businessPublish:A.productionPublish,supersede=item.bonus_type==='business'?A.businessSupersede:A.productionSupersede,withdraw=item.bonus_type==='business'?A.businessWithdraw:A.productionWithdraw;if(can(item,A.poolHistory))actions.push('<button class="quiet" data-action="history">读取历史</button>');if(can(item,publish))actions.push('<button class="primary" data-action="publish">发布草稿</button>');if(can(item,supersede))actions.push('<button class="quiet" data-action="supersede">替代纠错</button>');if(can(item,withdraw))actions.push('<button class="danger" data-action="withdraw">撤回</button>');const allocations=(item.allocations||[]).map(x=>'<div class="event"><strong>'+esc(x.person.display_name||x.person.id)+' · '+(x.ratio_basis_points/100).toFixed(2)+'%</strong>'+money(x.amount_minor,x.currency)+' · '+esc(x.reason)+'<br>Assignment '+esc(x.assignment.id)+' · r'+x.assignment.revision+(can(item,A.allocationHistory)?'<br><button class="quiet" data-action="allocation-history" data-allocation="'+esc(x.id)+'">读取分配历史</button>':'')+'</div>').join('');root.innerHTML='<div class="detail-block"><div class="card-head"><div><h3>'+typeName(item.bonus_type)+' · '+esc(item.state)+'</h3><div class="badges">'+(item.allowed_actions||[]).map(x=>'<span class="badge">'+esc(x)+'</span>').join('')+'</div></div><div class="actions">'+actions.join('')+'</div></div></div><div class="detail-block"><h3>金额与 Project</h3><div class="facts"><div class="fact"><small>奖金总额</small><strong>'+money(item.amount_minor,item.currency)+'</strong></div><div class="fact"><small>未分配</small><strong>'+money(item.unallocated_minor,item.currency)+'</strong></div><div class="fact"><small>Project revision</small><strong>'+item.project.revision+'</strong></div><div class="fact"><small>奖池 revision</small><strong>'+item.revision+'</strong></div></div></div><div class="detail-block"><h3>冻结来源</h3><p class="source">'+esc(item.source.type)+' '+esc(item.source.id)+' · r'+item.source.revision+' · '+esc(item.source.state)+'<br>digest '+esc(item.source.digest)+'<br>来源金额 '+money(item.source.total_amount_minor,item.source.currency)+'</p></div><div class="detail-block"><h3>固定策略</h3><p class="source">'+esc(item.policy.key)+' '+esc(item.policy.version)+' · '+item.policy.rate_basis_points+' bp · '+esc(item.policy.rounding)+'<br>'+esc(item.policy.formula)+'<br>digest '+esc(item.policy.parameters_digest)+'</p></div><div class="detail-block"><h3>参与人与分配</h3>'+allocations+'</div><div class="detail-block"><h3>纠错关系</h3><p class="source">'+relation(item)+'</p></div>'}
function explain(error,operation){if(error.status===401)return '访问凭证已失效；请重新登录或更新当前标签页凭证后重试。';if(error.status===403)return '当前凭证无权执行 '+operation+'；页面已收敛动作，请由 IAM 重新授权。';if(error.status===409)return operation+' 遇到 revision／状态冲突；请重新读取最新事实后再决定。';if(error.status===422)return operation+' 被来源或策略校验拒绝；请核对 Project、来源、Person 和 Assignment 的精确 revision。';if(error.status===503)return operation+' 的来源应用暂不可用；本次没有产生部分奖池，依赖恢复后可显式重试。';return operation+'失败：'+error.message+(error.retryable?'；依赖恢复后可重试。':'')}
async function load(){if(!state.token&&!gatewayMode){$('#credentialDialog').showModal();return}state.projectID=$('#projectID').value.trim().toLowerCase();if(!state.projectID)return;try{notice('正在读取奖池与服务端允许动作…');const data=await api('/api/v1/bonus-pools?project_id='+encodeURIComponent(state.projectID));state.items=data.items||[];state.collectionActions=data.allowed_actions||[];state.selected=state.items.find(x=>x.id===state.selected?.id)||null;$('#projectContext').textContent=state.projectID;$('#reload').disabled=false;render();renderDetail();notice('已读取 '+state.items.length+' 条奖池；页面动作已按服务端权限和当前状态收敛。','ok')}catch(error){state.items=[];state.collectionActions=[];state.selected=null;render();renderDetail();notice(explain(error,'读取奖池'),'error')}}
function allocationRow(value={}){const row=document.createElement('div');row.className='allocation-row';row.innerHTML='<label>Person ID<input name="person_id" required value="'+esc(value.person_id||'')+'"></label><label>Person revision<input name="person_revision" type="number" min="1" required value="'+esc(value.person_revision||'')+'"></label><label>Assignment ID<input name="assignment_id" required value="'+esc(value.assignment_id||'')+'"></label><label>Assignment revision<input name="assignment_revision" type="number" min="1" required value="'+esc(value.assignment_revision||'')+'"></label><label>分配比例（basis points）<input name="ratio_basis_points" type="number" min="1" max="10000" required value="'+esc(value.ratio_basis_points||10000)+'"></label><label>参与原因<input name="reason" required value="'+esc(value.reason||'')+'"></label><button type="button" class="quiet" data-remove-allocation>移除此人</button>';row.querySelector('[data-remove-allocation]').onclick=()=>{if($$('.allocation-row').length>1)row.remove()};return row}
function openDraft(type){const f=$('#draftForm');f.reset();f.elements.bonus_type.value=type;f.elements.policy_key.value='reference-oa-bonus-v1';f.elements.policy_version.value='1.0.0';f.elements.rate_basis_points.value='1000';f.elements.rounding.value='half_up';$('#draftTitle').textContent='建立'+typeName(type)+'草稿';$('#sourceLabel').firstChild.textContent=type==='business'?'Settlement ID':'Receipt Set ID';$('#allocationRows').replaceChildren(allocationRow({reason:type==='business'?'经营参与':'生产参与'}));$('#draftDialog').showModal()}
function draftPayload(form){const type=form.elements.bonus_type.value,rows=$$('.allocation-row'),allocations=rows.map(row=>({person:{id:row.querySelector('[name=person_id]').value.trim(),revision:Number(row.querySelector('[name=person_revision]').value)},assignment:{id:row.querySelector('[name=assignment_id]').value.trim(),revision:Number(row.querySelector('[name=assignment_revision]').value)},ratio_basis_points:Number(row.querySelector('[name=ratio_basis_points]').value),reason:row.querySelector('[name=reason]').value.trim()}));const sourceID=form.elements.source_id.value.trim(),sourceRevision=Number(form.elements.source_revision.value);return {command_id:crypto.randomUUID(),project:{id:state.projectID,revision:Number(form.elements.project_revision.value)},source:type==='business'?{settlement_id:sourceID,revision:sourceRevision}:{receipt_set_id:sourceID,revision:sourceRevision},policy:{key:form.elements.policy_key.value.trim(),version:form.elements.policy_version.value.trim(),rate_basis_points:Number(form.elements.rate_basis_points.value),rounding:form.elements.rounding.value},allocations}}
async function command(kind){const item=state.selected,reason=prompt(kind==='publish'?'请输入发布原因':'请输入撤回原因');if(!reason)return;const path='/api/v1/bonus-pools/'+item.id+(kind==='publish'?'/publication':'/withdrawal');try{notice(kind==='publish'?'正在发布草稿…':'正在撤回奖池…');await api(path,{method:'POST',body:JSON.stringify({command_id:crypto.randomUUID(),expected_revision:item.revision,reason})});await load();notice(kind==='publish'?'奖池已发布；冻结来源与分配历史可追溯。':'奖池已撤回；旧 revision 和审计历史仍保留。','ok')}catch(error){notice(explain(error,kind==='publish'?'发布':'撤回'),'error')}}
async function history(path,label){try{const data=await api(path);$('#historyList').innerHTML=(data.items||[]).map(x=>'<div class="event"><strong>'+esc(x.event_kind)+' · revision '+x.revision+'</strong>'+esc(x.reason||'')+'<br>'+new Date(x.occurred_at).toLocaleString('zh-CN')+'</div>').join('')||'<div class="empty">没有历史。</div>';notice('已读取'+label+'；历史为追加式事实。','ok')}catch(error){notice(explain(error,'读取'+label),'error')}}
function openSupersede(){const item=state.selected,candidates=state.items.filter(x=>x.id!==item.id&&x.bonus_type===item.bonus_type&&x.state==='draft'),select=$('#supersedeForm').elements.replacement_pool_id;select.replaceChildren(...candidates.map(x=>{const option=document.createElement('option');option.value=x.id;option.textContent=x.id+' · r'+x.revision+' · '+money(x.amount_minor,x.currency);return option}));if(!candidates.length){notice('先建立同类型的新草稿并核对，再回来执行替代纠错。','error');return}$('#supersedeForm').reset();$('#supersedeDialog').showModal()}
$$('.nav').forEach(b=>b.onclick=()=>{$$('.nav').forEach(x=>x.classList.toggle('active',x===b));$$('.view').forEach(v=>v.classList.toggle('active',v.id===b.dataset.view))});$$('[data-go]').forEach(b=>b.onclick=()=>$('.nav[data-view="'+b.dataset.go+'"]').click());$$('.mode').forEach(b=>b.onclick=()=>{$$('.mode').forEach(x=>x.classList.toggle('active',x===b));state.mode=b.dataset.mode;if(state.selected&&!filtered().some(x=>x.id===state.selected.id))state.selected=null;render();renderDetail()});
$('#openCredential').onclick=()=>{$('#token').value=state.token;$('#credentialDialog').showModal()};$('#credentialForm').onsubmit=e=>{if(e.submitter?.value==='cancel')return;state.token=$('#token').value.trim();sessionStorage.setItem('bonus-distribution-demo-token',state.token);$('#credentialState').textContent=state.token?'凭证已保存在当前标签页':'尚未连接';setTimeout(load)};$('#projectForm').onsubmit=e=>{e.preventDefault();load()};$('#reload').onclick=load;$('#newBusiness').onclick=()=>openDraft('business');$('#newProduction').onclick=()=>openDraft('production');$('#addAllocation').onclick=()=>$('#allocationRows').append(allocationRow());
$('#draftForm').onsubmit=async e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();const f=e.currentTarget,type=f.elements.bonus_type.value,payload=draftPayload(f),sum=payload.allocations.reduce((n,x)=>n+x.ratio_basis_points,0);if(sum!==10000){notice('分配比例合计必须为 10000 basis points；当前为 '+sum+'。','error');return}try{notice('正在读取真实来源并计算草稿…');await api('/api/v1/bonus-pools/'+(type==='business'?'business':'production')+'-drafts',{method:'POST',body:JSON.stringify(payload)});$('#draftDialog').close();state.mode=type;$('.mode[data-mode="'+type+'"]').click();await load();notice(typeName(type)+'草稿已建立；请先核对来源、策略和分配再发布。','ok')}catch(error){notice(explain(error,'建立'+typeName(type)+'草稿'),'error')}};
$('#detail').onclick=e=>{const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;if(action==='history')history('/api/v1/bonus-pools/'+state.selected.id+'/history','奖池历史');if(action==='allocation-history')history('/api/v1/bonus-allocations/'+target.dataset.allocation+'/history','分配历史');if(action==='publish')command('publish');if(action==='withdraw')command('withdraw');if(action==='supersede')openSupersede()};
$('#supersedeForm').onsubmit=async e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();const old=state.selected,replacement=state.items.find(x=>x.id===e.currentTarget.elements.replacement_pool_id.value);try{notice('正在原子替代旧奖池…');const result=await api('/api/v1/bonus-pools/supersession',{method:'POST',body:JSON.stringify({command_id:crypto.randomUUID(),published_pool_id:old.id,expected_published_revision:old.revision,replacement_pool_id:replacement.id,expected_replacement_revision:replacement.revision,reason:e.currentTarget.elements.reason.value.trim()})});$('#supersedeDialog').close();state.selected=result.published;await load();notice('纠错完成：旧奖池已 superseded，新草稿已发布，历史关联已保留。','ok')}catch(error){notice(explain(error,'替代纠错'),'error')}};
if(gatewayMode){$('#credentialState').textContent='已由 Gateway / IAM 保护';$('#openCredential').hidden=true}else{$('#credentialState').textContent=state.token?'凭证已保存在当前标签页':'尚未连接'}const query=new URLSearchParams(location.search),requested=query.get('project_id'),requestedMode=query.get('mode');if(['business','production'].includes(requestedMode))$('.mode[data-mode="'+requestedMode+'"]').click();if(requested){$('#projectID').value=requested;$('.nav[data-view="workspace"]').click();if(state.token||gatewayMode)load()}`
